<div class="page-heading"><div><span class="eyebrow">Parent · Account</span><h1>My profile</h1><p>Keep your contact details current for child records and booking communication.</p></div></div>
<section class="panel form-panel"><form method="post" action="<?= e(url('parent.profile')) ?>" data-validate><?= csrf_field() ?><div class="form-grid"><label>Full name<input name="name" value="<?= e($profile['name']) ?>" minlength="2" maxlength="100" required></label><label>Email address<input type="email" name="email" value="<?= e($profile['email']) ?>" maxlength="190" required></label><label>Phone number<input name="phone" value="<?= e($profile['phone']) ?>" maxlength="30"></label><label>Home address<input name="address" value="<?= e($profile['address']) ?>" minlength="5" maxlength="255" required></label><label class="span-2">New password <small>Leave blank to keep the existing password</small><span class="password-field"><input type="password" name="password" minlength="8" autocomplete="new-password"><button type="button" data-password-toggle>Show</button></span></label></div><button class="button" type="submit">Save profile</button></form></section>
